<template><ion-page><ion-content><main><h1>Criar conta</h1><form @submit.prevent="submit"><ion-input v-model="name" label="Nome" label-placement="stacked" fill="outline"/><ion-input v-model="email" label="E-mail" label-placement="stacked" type="email" fill="outline"/><ion-input v-model="password" label="Senha (mín. 6)" label-placement="stacked" type="password" fill="outline"/><ion-input v-model="confirm" label="Confirmar senha" label-placement="stacked" type="password" fill="outline"/><ion-text color="danger" v-if="error">{{error}}</ion-text><ion-button expand="block" type="submit">Criar conta</ion-button></form><p><router-link to="/login">Voltar para login</router-link></p></main></ion-content></ion-page></template>
<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{IonButton,IonContent,IonInput,IonPage,IonText}from'@ionic/vue';import{register}from'../services/storage';const router=useRouter(),name=ref(''),email=ref(''),password=ref(''),confirm=ref(''),error=ref('');async function submit(){if(!name.value||!/\S+@\S+\.\S+/.test(email.value)||password.value.length<6||password.value!==confirm.value){error.value='Verifique os dados.';return}await register({name:name.value,email:email.value,password:password.value});router.replace('/login')}</script><style scoped>main{max-width:420px;margin:auto;padding:90px 26px}form{display:grid;gap:15px}ion-button{height:50px}a{color:#386dd6}</style>
